#include "vmf_cpu.hpp"

#include <bit>

#if defined(_MSC_VER)
#pragma warning(push, 0)
#endif
#include "vmf_kernel.cpp"   // generated by slangc into the build tree
#if defined(_MSC_VER)
#pragma warning(pop)
#endif

namespace ohao::sampling {

namespace {

using F4 = Vector<float, 4>;

F4 f4(float x, float y, float z, float w) {
    F4 v{};
    v.x = x;
    v.y = y;
    v.z = z;
    v.w = w;
    return v;
}

// Runs one item: rows 0-3 in, rows 4-5 out.
std::array<F4, 6> runItem(const std::array<F4, 4>& in) {
    F4 io[6]{};
    for (int i = 0; i < 4; ++i) io[i] = in[i];
    GlobalParams_0 globals{};
    globals.io_0.data = io;
    globals.io_0.count = 6;
    ComputeVaryingInput range{};
    range.startGroupID = {0, 0, 0};
    range.endGroupID = {1, 1, 1};
    ::run(&range, nullptr, &globals);
    return {io[0], io[1], io[2], io[3], io[4], io[5]};
}

F4 stateRow1(const GuideStateCpu& s) { return f4(s.w, s.y[0], s.y[1], s.y[2]); }
F4 stateRow2(const GuideStateCpu& s, float frame) {
    return f4(s.r, std::bit_cast<float>(s.nt), std::bit_cast<float>(s.check), frame);
}

} // namespace

float vmfPdf(const Vec3& dir, const Vec3& mu, float kappa) {
    return runItem({f4(0, 0, 0, 0), f4(dir[0], dir[1], dir[2], 0), f4(mu[0], mu[1], mu[2], kappa), F4{}})[4].x;
}

Vec3 vmfSample(const Vec3& mu, float kappa, float u0, float u1) {
    const auto o = runItem({f4(1, 0, 0, 0), f4(u0, u1, 0, 0), f4(mu[0], mu[1], mu[2], kappa), F4{}});
    return {o[4].x, o[4].y, o[4].z};
}

float vmfKappa(float meanCosine) { return runItem({f4(2, 0, 0, 0), f4(meanCosine, 0, 0, 0), F4{}, F4{}})[4].x; }

float vmfMeanCosine(float kappa) { return runItem({f4(3, 0, 0, 0), f4(kappa, 0, 0, 0), F4{}, F4{}})[4].x; }

GuideStateCpu guideUpdate(const GuideStateCpu& s, const Vec3& x, const Vec3& target, float f, uint32_t frame) {
    const auto o = runItem({f4(4, target[0], target[1], target[2]), stateRow1(s), stateRow2(s, float(frame)),
                            f4(x[0], x[1], x[2], f)});
    GuideStateCpu r;
    r.w = o[4].x;
    r.y = {o[4].y, o[4].z, o[4].w};
    r.r = o[5].x;
    r.nt = std::bit_cast<uint32_t>(o[5].y);
    r.check = std::bit_cast<uint32_t>(o[5].z);
    return r;
}

bool guideLobe(const GuideStateCpu& s, const Vec3& x, float n0, Vec3& mu, float& kappa) {
    const auto o = runItem({f4(5, 0, 0, 0), stateRow1(s), stateRow2(s, 0.0f), f4(x[0], x[1], x[2], n0)});
    mu = {o[4].x, o[4].y, o[4].z};
    kappa = o[4].w;
    return o[5].x != 0.0f;
}

} // namespace ohao::sampling
